import throttle from 'lodash.throttle';
import { IThrottleOptions } from '../types';

export function Throttle(duration: number, options?: IThrottleOptions) {
    return function throttleDecorator(target: object, propertyKey: string, descriptor: PropertyDescriptor) {
        return {
            configurable: true,
            enumerable: descriptor.enumerable,
            get(this: { [key: string]: any }) {
                Object.defineProperty(this, propertyKey, {
                    configurable: true,
                    enumerable: descriptor.enumerable,
                    value: throttle(descriptor.value, duration, options)
                });

                return this[propertyKey];
            }
        };
    };
}

export { throttle };